func (o *ScheduledTask) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "CreatedByUser":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("scheduledTask cannot load %T as %q", retrieved, name)
		}

		o.R.CreatedByUser = rel

		if rel != nil {
			rel.R.CreatedByScheduledTasks = ScheduledTaskSlice{o}
		}
		return nil
	case "GameServer":
		rel, ok := retrieved.(*GameServer)
		if !ok {
			return fmt.Errorf("scheduledTask cannot load %T as %q", retrieved, name)
		}

		o.R.GameServer = rel

		if rel != nil {
			rel.R.ScheduledTasks = ScheduledTaskSlice{o}
		}
		return nil
	case "ScheduledTaskLogs":
		rels, ok := retrieved.(ScheduledTaskLogSlice)
		if !ok {
			return fmt.Errorf("scheduledTask cannot load %T as %q", retrieved, name)
		}

		o.R.ScheduledTaskLogs = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.ScheduledTask = o
			}
		}
		return nil
	default:
		return fmt.Errorf("scheduledTask has no relationship %q", name)
	}
}

